from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    k = len(alphabet)
    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}

    children = [[-1] * k]
    bad = [False]

    for word in banned:
        u = 0
        for ch in word:
            c = char_to_idx[ch]
            nxt = children[u][c]
            if nxt == -1:
                nxt = len(children)
                children[u][c] = nxt
                children.append([-1] * k)
                bad.append(False)
            u = nxt
        bad[u] = True

    fail = [0] * len(children)
    q = deque()
    for c in range(k):
        v = children[0][c]
        if v != -1:
            fail[v] = 0
            q.append(v)
        else:
            children[0][c] = 0

    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for c in range(k):
            v = children[u][c]
            if v != -1:
                fail[v] = children[fail[u]][c]
                q.append(v)
            else:
                children[u][c] = children[fail[u]][c]

    good = [i for i, is_bad in enumerate(bad) if not is_bad]
    m = len(good)
    good_idx = {u: idx for idx, u in enumerate(good)}

    base = [[0] * m for _ in range(m)]
    for i, u in enumerate(good):
        row = base[i]
        for c in range(k):
            v = children[u][c]
            if not bad[v]:
                row[good_idx[v]] += 1

    vec = [0] * m
    vec[0] = 1

    while n > 0:
        if n & 1:
            nxt = [0] * m
            for i in range(m):
                vi = vec[i]
                if vi:
                    row = base[i]
                    for j in range(m):
                        nxt[j] += vi * row[j]
            vec = [x % MOD for x in nxt]
        n >>= 1
        if n:
            nxt_base = [[0] * m for _ in range(m)]
            for i in range(m):
                row_i = base[i]
                out_i = nxt_base[i]
                for p in range(m):
                    val = row_i[p]
                    if val:
                        row_p = base[p]
                        for j in range(m):
                            out_i[j] += val * row_p[j]
                for j in range(m):
                    out_i[j] %= MOD
            base = nxt_base

    return sum(vec) % MOD
